package com.smartattendance.service;
import com.smartattendance.dto.*;import com.smartattendance.exception.ResourceNotFoundException;import com.smartattendance.model.*;import com.smartattendance.repository.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import java.util.List;
@Service
public class AttendanceService{private final AttendanceSessionRepository sessions;private final AttendanceRecordRepository records;private final SubjectService subjects;private final FacultyService faculty;private final StudentService students;public AttendanceService(AttendanceSessionRepository sessions,AttendanceRecordRepository records,SubjectService subjects,FacultyService faculty,StudentService students){this.sessions=sessions;this.records=records;this.subjects=subjects;this.faculty=faculty;this.students=students;}public Page<AttendanceSessionResponse> searchSessions(String q,Pageable p){return(q==null||q.isBlank()?sessions.findAll(p):sessions.findByTopicContainingIgnoreCaseOrSessionDate(q,null,p)).map(this::toSessionResponse);}public AttendanceSessionResponse createSession(AttendanceSessionRequest r){AttendanceSession s=new AttendanceSession();s.setSubject(subjects.find(r.subjectId()));s.setFaculty(faculty.find(r.facultyId()));s.setSessionDate(r.sessionDate());s.setTopic(r.topic());return toSessionResponse(sessions.save(s));}public AttendanceSessionResponse updateSession(Long id,AttendanceSessionRequest r){AttendanceSession s=findSession(id);s.setSubject(subjects.find(r.subjectId()));s.setFaculty(faculty.find(r.facultyId()));s.setSessionDate(r.sessionDate());s.setTopic(r.topic());return toSessionResponse(sessions.save(s));}public AttendanceSessionResponse getSession(Long id){return toSessionResponse(findSession(id));}public void deleteSession(Long id){sessions.delete(findSession(id));}public Page<AttendanceRecordResponse> searchRecords(Long studentId,Long sessionId,Pageable p){return records.filter(studentId,sessionId,p).map(this::toRecordResponse);}public AttendanceRecordResponse mark(AttendanceRecordRequest r){AttendanceRecord rec=records.findBySessionIdAndStudentId(r.sessionId(),r.studentId()).orElseGet(AttendanceRecord::new);rec.setSession(findSession(r.sessionId()));rec.setStudent(students.find(r.studentId()));rec.setStatus(r.status());rec.setRemarks(r.remarks());return toRecordResponse(records.save(rec));}public AttendanceRecordResponse updateRecord(Long id,AttendanceRecordRequest r){AttendanceRecord rec=findRecord(id);rec.setSession(findSession(r.sessionId()));rec.setStudent(students.find(r.studentId()));rec.setStatus(r.status());rec.setRemarks(r.remarks());return toRecordResponse(records.save(rec));}public AttendanceRecordResponse getRecord(Long id){return toRecordResponse(findRecord(id));}public void deleteRecord(Long id){records.delete(findRecord(id));}public ReportResponse studentReport(Long studentId){Student s=students.find(studentId);long total=records.countByStudentId(studentId);long present=records.countByStudentIdAndStatusIn(studentId,List.of(AttendanceStatus.PRESENT,AttendanceStatus.LATE));double pct=total==0?0.0:Math.round((present*10000.0)/total)/100.0;return new ReportResponse(s.getId(),s.getName(),total,present,pct);}private AttendanceSession findSession(Long id){return sessions.findById(id).orElseThrow(()->new ResourceNotFoundException("Attendance session",id));}private AttendanceRecord findRecord(Long id){return records.findById(id).orElseThrow(()->new ResourceNotFoundException("Attendance record",id));}private AttendanceSessionResponse toSessionResponse(AttendanceSession s){return new AttendanceSessionResponse(s.getId(),s.getSubject().getId(),s.getSubject().getName(),s.getFaculty().getId(),s.getFaculty().getName(),s.getSessionDate(),s.getTopic());}private AttendanceRecordResponse toRecordResponse(AttendanceRecord r){return new AttendanceRecordResponse(r.getId(),r.getSession().getId(),r.getStudent().getId(),r.getStudent().getName(),r.getStatus(),r.getMarkedAt(),r.getRemarks());}}
